                return true;
            }

            $job = $jobs[$index];

            $used = [];
            for ($i = 0; $i < $k; $i++) {
                if ($workerTimes[$i] + $job <= $limit && !isset($used[$workerTimes[$i]])) {
                    $workerTimes[$i] += $job;
                    if (canAssign($jobs, $workerTimes, $limit, $index + 1, $k)) {
                        return true;
