                    $workerTimes[$i] -= $job;
                    $used[$workerTimes[$i]] = true;

                    // If worker has no jobs assigned and still didn't lead to solution, no point trying next empty worker
                    if ($workerTimes[$i] == 0) {
                        break;
                    }
                }
            }
            return false;
        }

